/**
 * Billing-period arithmetic: where a period ends, what a full period costs and
 * what a change made mid-period owes. Pure functions only, so the renewal job,
 * the seat and plan changes and their tests all agree on the same numbers.
 */
import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export interface PeriodSpan {
  readonly start: Date;
  readonly end: Date;
}

/** Months covered by one period of the given interval. */
export function monthsPerInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * The end of a period of `months` that starts at `start`: the same day and time
 * of day that many months later, or the last day of that month when it has no
 * such day (31 Jan → 28 Feb, 29 Feb → 28 Feb). Calendar arithmetic in UTC.
 */
export function periodEndAfter(start: Date, months: number): Date {
  const monthIndex = start.getUTCMonth() + months;
  const year = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = ((monthIndex % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  return new Date(
    Date.UTC(
      year,
      month,
      Math.min(start.getUTCDate(), lastDay),
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/**
 * The periods a renewal opens from `periodEnd` onwards: one per elapsed
 * interval, each starting where the previous one ended, until the newest
 * period's end lies after `now`. Empty when `periodEnd` is still in the future.
 */
export function periodsToOpen(
  periodEnd: Date,
  months: number,
  now: Date,
): readonly PeriodSpan[] {
  const periods: PeriodSpan[] = [];
  let start = periodEnd;

  while (start.getTime() <= now.getTime()) {
    const end = periodEndAfter(start, months);
    periods.push({ start, end });
    start = end;
  }

  return periods;
}

/** The charge for `seats` seats at `priceCentsPerSeatMonthly` over `months`, in cents. */
export function chargeCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  months: number,
): number {
  return priceCentsPerSeatMonthly * seats * months;
}

/**
 * Whole or started days from `now` to the period end, so 14 days and 22 hours
 * left counts as 15. Zero once the period end has been reached.
 */
export function daysLeft(now: Date, periodEnd: Date): number {
  const remainingMs = periodEnd.getTime() - now.getTime();
  return remainingMs > 0 ? Math.ceil(remainingMs / MS_PER_DAY) : 0;
}

/** The whole days between a period's start and end, rounded, and at least one. */
export function daysInPeriod(periodStart: Date, periodEnd: Date): number {
  const days = Math.round(
    (periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY,
  );
  return Math.max(1, days);
}

/**
 * The share of a full-period charge owed for a change made at `now` inside the
 * period, scaled by the days left over the days in the period and rounded down
 * to whole cents.
 */
export function prorateCents(
  fullCents: number,
  now: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  const days = daysInPeriod(periodStart, periodEnd);
  const left = Math.min(daysLeft(now, periodEnd), days);
  return Math.floor((fullCents * left) / days);
}

