/**
 * Applies a billing change and writes the invoices it owes in one transaction,
 * so a crash cannot leave a period advanced without its invoice, or an invoice
 * for a period that never took effect.
 */
export async function commitSubscriptionChange(
  orgId: OrgId,
  patch: SubscriptionPatch,
  invoiceDrafts: readonly InvoiceDraft[],
): Promise<{ subscription: Subscription; invoices: readonly Invoice[] }> {
  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Subscription for org ${orgId} not found`);

    const invoices = invoiceDrafts.map((draft) =>
      insertNumberedInvoice(tx, orgId, draft),
    );

    return { subscription: toSubscription(row), invoices };
  });
}

/**
 * Every subscription of every live workspace that the renewal job may act on:
 * `active` ones (renewal) and `canceled` ones (ending). Archived workspaces are
 * skipped entirely. Cross-tenant by design, like the trial sweep below.
 */
export async function listRenewableSubscriptions(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        isNull(organizations.archivedAt),
        inArray(subscriptions.status, ["active", "canceled"]),
      ),
    )
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */

