export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const terms = planChangeTerms(current, input, new Date());
  const subscription = await commitChange(
    input.orgId,
    actor.userId,
    terms.patch,
    terms.drafts,
  );

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: current.plan,
    to: input.plan,
  });

  return subscription;
}

/**
 * Adding seats to a paid, active subscription charges the added seats for the
 * rest of the current period. Removing seats charges and credits nothing, and
 * the free plan and trials are never charged.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const plan = current.plan;

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const added = input.seats - current.seats;
  const drafts: InvoiceDraft[] =
    current.status === "active" && plan !== "free" && added > 0
      ? [
          proratedDraft(
            current,
            new Date(),
            chargeCents(
              priceOf(plan),
              added,
              monthsPerInterval(current.interval),
            ),
          ),
        ]
      : [];

  return commitChange(input.orgId, actor.userId, { seats: input.seats }, drafts);
}

/**
 * Opens every period a subscription owes by `now` and invoices each paid one at
 * the seat count in force now. Free-plan periods move on without invoices.
 * Returns how many periods were opened; zero when no period had ended.
 */
export async function renewSubscription(
  subscription: Subscription,
  now: Date,
): Promise<number> {
  if (subscription.status !== "active") return 0;

  const months = monthsPerInterval(subscription.interval);
  const periods = periodsToOpen(
    new Date(subscription.currentPeriodEnd),
    months,
    now,
  );
  const latest = periods[periods.length - 1];
  if (latest === undefined) return 0;

  const drafts: InvoiceDraft[] =
    subscription.plan === "free"
      ? []
      : periods.map((period) => ({
          amountCents: chargeCents(
            priceOf(subscription.plan),
            subscription.seats,
            months,
          ),
          periodStart: toIsoTimestamp(period.start),
          periodEnd: toIsoTimestamp(period.end),
        }));

  await commitChange(
    subscription.orgId,
    null,
    {
      currentPeriodStart: toIsoTimestamp(latest.start),
      currentPeriodEnd: toIsoTimestamp(latest.end),
    },
    drafts,
  );

  return periods.length;
}

/**
 * Ends a canceled subscription on its cancellation date: the workspace moves to
 * the free plan with a monthly period starting then, and nothing is invoiced.
 * Free periods that have already elapsed are opened in the same pass, so
 * running again at the same instant changes nothing. Returns whether it ended.
 */
export async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.status !== "canceled" || subscription.cancelAt === null) {
    return false;
  }

  const cancelledAt = new Date(subscription.cancelAt);
  if (cancelledAt.getTime() > now.getTime()) return false;

  const first = { start: cancelledAt, end: periodEndAfter(cancelledAt, 1) };
  const periods = [first, ...periodsToOpen(first.end, 1, now)];
  const latest = periods[periods.length - 1] ?? first;

  await commitChange(
    subscription.orgId,
    null,
    {
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: toIsoTimestamp(latest.start),
      currentPeriodEnd: toIsoTimestamp(latest.end),
    },
    [],
  );

  if (subscription.plan !== "free") {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from: subscription.plan,
      to: "free",
    });
  }

  return true;
}

