/** Monthly price per seat of a plan, in cents. */
function priceOf(plan: PlanId): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly;
}

/**
 * What a plan change writes, decided from the subscription as it stands at `now`:
 *  - during a trial nothing is charged and the trial period is kept, so the
 *    first invoice comes when it ends;
 *  - leaving the free plan while active opens a fresh period from `now` with the
 *    chosen interval, invoiced in full;
 *  - moving between two paid plans while active charges the per-seat increase,
 *    prorated over the current period; a downgrade or the same plan owes nothing;
 *  - anything else (a move to free, a canceled or past-due subscription) charges
 *    nothing and keeps the period.
 */
function planChangeTerms(
  current: Subscription,
  input: ChangePlanInput,
  now: Date,
): ChangeTerms {
  const base: SubscriptionPatch = {
    plan: input.plan,
    interval: input.interval,
    status: current.status === "canceled" ? "canceled" : "active",
  };

  if (current.status === "active" && current.plan === "free" && input.plan !== "free") {
    const months = monthsPerInterval(input.interval);
    const periodStart = toIsoTimestamp(now);
    const periodEnd = toIsoTimestamp(periodEndAfter(now, months));

    return {
      patch: { ...base, currentPeriodStart: periodStart, currentPeriodEnd: periodEnd },
      drafts: [
        {
          amountCents: chargeCents(priceOf(input.plan), current.seats, months),
          periodStart,
          periodEnd,
        },
      ],
    };
  }

  if (current.status === "active" && current.plan !== "free" && input.plan !== "free") {
    const increase = Math.max(0, priceOf(input.plan) - priceOf(current.plan));
    const fullCents = chargeCents(
      increase,
      current.seats,
      monthsPerInterval(current.interval),
    );

    return { patch: base, drafts: [proratedDraft(current, now, fullCents)] };
  }

  return { patch: base, drafts: [] };
}

/** A prorated share of `fullCents` for a change made at `now`, invoiced against the current period. */
function proratedDraft(
  subscription: Subscription,
  now: Date,
  fullCents: number,
): InvoiceDraft {
  return {
    amountCents: prorateCents(
      fullCents,
      now,
      new Date(subscription.currentPeriodStart),
      new Date(subscription.currentPeriodEnd),
    ),
    periodStart: subscription.currentPeriodStart,
    periodEnd: subscription.currentPeriodEnd,
  };
}

/**
