 * Renews active subscriptions whose period has ended and ends canceled ones on their cancellation date.
 *
 * Must call (do not reimplement): renewSubscription, endCancellation
 */
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import {
  endCancellation,
  renewSubscription,
} from "@/server/services/billing-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const logger = createLogger("billing-renewal-job");

/**
 * The renewal sweep. Every live workspace's subscription is considered, however
 * many there are; archived workspaces are skipped by the repository. Trialing and
 * past-due subscriptions are never touched here — the trial-expiry job owns trials.
 *
 * A failure on one subscription is counted and logged, and does not stop the sweep.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listRenewableSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const opened = await renewSubscription(subscription, now);
        const ended = await endCancellation(subscription, now);

        if (opened > 0 || ended) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

