  monthsPerInterval,
  periodEndAfter,
  periodsToOpen,
  prorateCents,
} from "@/lib/billing-period";

const at = (iso: string): Date => new Date(iso);

describe("lib/billing-period", () => {
  it("counts a month as one period and a year as twelve", () => {
    expect(monthsPerInterval("monthly")).toBe(1);
    expect(monthsPerInterval("annual")).toBe(12);
  });

  it("ends a monthly period on the same day next month at the same time of day", () => {
    expect(
      periodEndAfter(at("2026-03-15T10:30:00.000Z"), 1).toISOString(),
    ).toBe("2026-04-15T10:30:00.000Z");
  });

  it("clamps a monthly period to the last day of a shorter month", () => {
    expect(
      periodEndAfter(at("2026-01-31T00:00:00.000Z"), 1).toISOString(),
    ).toBe("2026-02-28T00:00:00.000Z");
  });

  it("carries a clamped day forward into the next period", () => {
    const february = at("2026-02-28T00:00:00.000Z");
    expect(periodEndAfter(february, 1).toISOString()).toBe(
      "2026-03-28T00:00:00.000Z",
    );
  });

  it("ends an annual period on the same day and month the following year", () => {
    expect(
      periodEndAfter(at("2026-06-01T00:00:00.000Z"), 12).toISOString(),
    ).toBe("2027-06-01T00:00:00.000Z");
  });

  it("clamps an annual period that starts on 29 February", () => {
    expect(
      periodEndAfter(at("2028-02-29T00:00:00.000Z"), 12).toISOString(),
    ).toBe("2029-02-28T00:00:00.000Z");
  });

  it("opens one period per elapsed interval until the newest one ends after now", () => {
    const periods = periodsToOpen(
      at("2026-01-01T00:00:00.000Z"),
      1,
      at("2026-03-31T12:00:00.000Z"),
    );

    expect(periods.map((period) => period.start.toISOString())).toEqual([
      "2026-01-01T00:00:00.000Z",
      "2026-02-01T00:00:00.000Z",
      "2026-03-01T00:00:00.000Z",
    ]);
    expect(periods.at(-1)?.end.toISOString()).toBe("2026-04-01T00:00:00.000Z");
  });

  it("opens nothing while the period end is still ahead", () => {
    expect(
      periodsToOpen(
        at("2026-05-01T00:00:00.000Z"),
        1,
        at("2026-04-30T00:00:00.000Z"),
      ),
    ).toEqual([]);
  });

  it("counts a started day as a whole day left", () => {
    const end = at("2026-02-01T00:00:00.000Z");

    // 14 days and 22 hours left.
    expect(daysLeft(at("2026-01-17T02:00:00.000Z"), end)).toBe(15);
  });

  it("has no days left once the period end has been reached", () => {
    const end = at("2026-02-01T00:00:00.000Z");

