    expect(daysLeft(at("2026-02-03T00:00:00.000Z"), end)).toBe(0);
  });

  it("counts the whole days in a period, at least one", () => {
    expect(
      daysInPeriod(
        at("2026-01-01T00:00:00.000Z"),
        at("2027-01-01T00:00:00.000Z"),
      ),
    ).toBe(365);
    expect(
      daysInPeriod(
        at("2026-01-01T00:00:00.000Z"),
        at("2026-01-01T00:00:00.000Z"),
      ),
    ).toBe(1);
  });

  it("charges seats times months at the monthly price", () => {
    expect(chargeCents(1_900, 2, 12)).toBe(45_600);
  });

  it("prorates a mid-period change by days left over days in the period, rounded down", () => {
    const start = at("2026-01-01T00:00:00.000Z");
    const end = at("2026-02-01T00:00:00.000Z");
    const full = chargeCents(1_900, 2, 1);

    // 12 of the 31 days are left: 3800 * 12 / 31 = 1470.97…
    expect(
      prorateCents(full, at("2026-01-20T00:00:00.000Z"), start, end),
    ).toBe(1_470);
  });

  it("charges the full amount for a change at the very start of a period", () => {
    const start = at("2026-01-01T00:00:00.000Z");
    const end = at("2026-02-01T00:00:00.000Z");

    expect(prorateCents(3_800, start, start, end)).toBe(3_800);
  });

  it("charges nothing for a change made once the period has ended", () => {
    const start = at("2026-01-01T00:00:00.000Z");
    const end = at("2026-02-01T00:00:00.000Z");

    expect(prorateCents(3_800, at("2026-02-02T00:00:00.000Z"), start, end)).toBe(0);
  });
});

