/**
 * Renewal job, cancellations, and the mid-period charges made by seat and plan
 * changes. Each case sets its own subscription state through the repository so
 * the periods under test are exact.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { periodEndAfter } from "@/lib/billing-period";
import { subscribe } from "@/lib/event-bus";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import type { SubscriptionPatch } from "@/server/repositories/subscription-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

const DAY_MS = 24 * 60 * 60 * 1000;

/** The instant the renewal job is run at in the period-boundary cases. */
const NOW = new Date("2026-06-01T07:00:00.000Z");

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

function stamp(iso: string) {
  return toIsoTimestamp(new Date(iso));
}

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function setSubscription(
  orgId: OrgId,
  patch: SubscriptionPatch,
): Promise<void> {
  await subscriptionRepo.commitSubscriptionChange(orgId, patch, []);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("the renewal job", () => {
  it("opens the next paid period and invoices it at the seats in force", async () => {
    const tenant = await createTenant("renew-paid", "growth");
    await setSubscription(tenant.org.id, {
      status: "active",
      seats: 4,
      interval: "monthly",
      currentPeriodStart: stamp("2026-05-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-06-01T00:00:00.000Z"),
    });

    const result = await runBillingRenewalJob(NOW);

    expect(result.kind).toBe("billing-renewal");
    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      status: "active",
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toMatchObject([
      {
        number: "INV-0001",
        amountCents: 7_600,
        currency: "usd",
        periodStart: "2026-06-01T00:00:00.000Z",
        periodEnd: "2026-07-01T00:00:00.000Z",
        paidAt: null,
      },
    ]);
  });

  it("catches up three months behind with three consecutive invoices, then changes nothing on a second run", async () => {
    const tenant = await createTenant("renew-behind", "starter");
    await setSubscription(tenant.org.id, {
      status: "active",
      seats: 2,
      interval: "monthly",
      currentPeriodStart: stamp("2026-02-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-03-01T00:00:00.000Z"),
    });
    const asOf = new Date("2026-05-31T00:00:00.000Z");

    await runBillingRenewalJob(asOf);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-05-01T00:00:00.000Z",
      "2026-04-01T00:00:00.000Z",
      "2026-03-01T00:00:00.000Z",
    ]);
    expect(invoices.map((invoice) => invoice.number)).toEqual([
      "INV-0003",
      "INV-0002",
      "INV-0001",
    ]);
    expect(invoices.map((invoice) => invoice.amountCents)).toEqual([
      1_800, 1_800, 1_800,
    ]);

    const settled = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(settled).toMatchObject({
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(asOf);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(settled);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(3);
  });

  it("moves a free workspace's periods on without invoicing", async () => {
    const tenant = await createTenant("renew-free", "free");
    await setSubscription(tenant.org.id, {
      status: "active",
      currentPeriodStart: stamp("2026-05-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-06-01T00:00:00.000Z"),
    });

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      plan: "free",
      currentPeriodStart: "2026-06-01T00:00:00.000Z",
      currentPeriodEnd: "2026-07-01T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("leaves trialing and past-due subscriptions alone", async () => {
    const trial = await createTenant("renew-trial", "growth");
    const pastDue = await createTenant("renew-past-due", "growth");
    const overdue = {
      currentPeriodStart: stamp("2026-01-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-02-01T00:00:00.000Z"),
    };
    await setSubscription(trial.org.id, overdue);
    await setSubscription(pastDue.org.id, { ...overdue, status: "past_due" });

    await runBillingRenewalJob(NOW);

    for (const org of [trial.org, pastDue.org]) {
      expect(await subscriptionRepo.findSubscription(org.id)).toMatchObject(overdue);
      expect(await invoiceRepo.listInvoices(org.id)).toEqual([]);
    }
  });

  it("skips archived workspaces entirely", async () => {
    const tenant = await createTenant("renew-archived", "growth");
    await setSubscription(tenant.org.id, {
      status: "active",
      currentPeriodStart: stamp("2026-05-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-06-01T00:00:00.000Z"),
    });
    await orgRepo.archiveOrg(tenant.org.id);

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
  });

  it("ends a cancellation on its date: free from then on, a monthly period, no invoice, one announcement", async () => {
    const tenant = await createTenant("cancel-end", "growth");
    await setSubscription(tenant.org.id, {
      status: "canceled",
      cancelAt: stamp("2026-05-31T00:00:00.000Z"),
      currentPeriodStart: stamp("2026-05-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-05-31T00:00:00.000Z"),
    });
    const changed = capture("billing.plan_changed");

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      plan: "free",
      status: "active",
      cancelAt: null,
      currentPeriodStart: "2026-05-31T00:00:00.000Z",
      currentPeriodEnd: "2026-06-30T00:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);

    await runBillingRenewalJob(NOW);

    const ours = changed.filter((event) => event.orgId === tenant.org.id);
    expect(ours).toEqual([
      expect.objectContaining({ from: "growth", to: "free", actorId: null }),
    ]);
  });

  it("does not end a cancellation before its date, whatever the period end says", async () => {
    const tenant = await createTenant("cancel-early", "growth");
    await setSubscription(tenant.org.id, {
      status: "canceled",
      cancelAt: stamp("2026-07-01T00:00:00.000Z"),
      currentPeriodStart: stamp("2026-04-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-05-01T00:00:00.000Z"),
    });

    await runBillingRenewalJob(NOW);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      plan: "growth",
      status: "canceled",
      cancelAt: "2026-07-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    });
  });

  it("publishes, audits and announces each invoice once, to the owner only", async () => {
    const tenant = await createTenant("renew-announce", "growth");
    await setSubscription(tenant.org.id, {
      status: "active",
      seats: 1,
      interval: "monthly",
      currentPeriodStart: stamp("2026-05-01T00:00:00.000Z"),
      currentPeriodEnd: stamp("2026-06-01T00:00:00.000Z"),
    });
    const issued = capture("billing.invoice_issued");

    await runBillingRenewalJob(NOW);
    await runBillingRenewalJob(NOW);

    const ours = issued.filter((event) => event.orgId === tenant.org.id);
    expect(ours).toMatchObject([
      {
        invoiceNumber: "INV-0001",
        amountCents: 1_900,
        periodStart: "2026-06-01T00:00:00.000Z",
        periodEnd: "2026-07-01T00:00:00.000Z",
        actorId: null,
      },
    ]);

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toMatchObject([
      { action: "billing.invoice_issued", subjectKind: "subscription", subjectId: tenant.org.id },
    ]);

    const inbox = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(inbox.items.filter((item) => item.kind === "invoice_issued")).toHaveLength(1);

    const member = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(member.items.filter((item) => item.kind === "invoice_issued")).toEqual([]);
  });
});

describe("mid-period changes", () => {
  it("charges added seats for the rest of the current period, and nothing for removed seats", async () => {
    const tenant = await createTenant("seats-prorate", "growth");
    const t0 = Date.now();
    const start = toIsoTimestamp(new Date(t0 - 10 * DAY_MS));
    const end = toIsoTimestamp(new Date(t0 + 20 * DAY_MS));
    await setSubscription(tenant.org.id, {
      status: "active",
      seats: 2,
      interval: "monthly",
      currentPeriodStart: start,
      currentPeriodEnd: end,
    });

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 5,
    });

    // Three seats at 1,900 for 20 of the period's 30 days: 5,700 * 20 / 30.
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toMatchObject([
      { amountCents: 3_800, periodStart: start, periodEnd: end },
    ]);
    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      seats: 5,
      currentPeriodStart: start,
      currentPeriodEnd: end,
    });

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 3,
    });

    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
  });

  it("charges nothing for seat changes during a trial or on the free plan", async () => {
    const trial = await createTenant("seats-trial", "growth");
    const free = await createTenant("seats-free", "free");

    await billingService.updateSeats(trial.actors.owner, {
      orgId: trial.org.id,
      seats: 6,
    });
    await billingService.updateSeats(free.actors.owner, {
      orgId: free.org.id,
      seats: 2,
    });

    expect(await invoiceRepo.listInvoices(trial.org.id)).toEqual([]);
    expect(await invoiceRepo.listInvoices(free.org.id)).toEqual([]);
  });

